import XCTest
@testable import LukiFittiModels

/// Verifies the bundled boss recipes decode and that `bossBounds`/`raidPhaseFor`
/// return the values exported from the TypeScript implementation in
/// `raid_boss_vectors.json` (regenerated by `yarn raid:export`; `raid:check`
/// fails in CI when it goes stale).
final class RaidBossPortTests: XCTestCase {
    private struct Vectors: Decodable {
        struct Bound: Decodable {
            var center: [Double]
            var radius: Double
            var halfWidth: Double
            var halfHeight: Double
        }
        struct PhaseCase: Decodable {
            var damage: Double
            var maxHp: Double
            var phase: Int
        }
        var bounds: [String: Bound]
        var phases: [PhaseCase]
    }

    private func loadVectors() throws -> Vectors {
        guard let url = Bundle.module.url(forResource: "raid_boss_vectors", withExtension: "json") else {
            throw XCTSkip("raid_boss_vectors.json not in the test bundle")
        }
        return try JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }

    func testBossesDecode() {
        XCTAssertEqual(RaidBossCatalog.bosses.count, 8)
        for boss in RaidBossCatalog.bosses {
            XCTAssertLessThanOrEqual(boss.parts.count, 40, boss.slug)
            XCTAssertEqual(Set(boss.parts.map(\.id)).count, boss.parts.count, boss.slug)
            XCTAssertFalse(boss.weakTo.isEmpty, boss.slug)
        }
    }

    func testBoundsMatchTypeScript() throws {
        let vectors = try loadVectors()
        XCTAssertEqual(vectors.bounds.count, 8)
        for boss in RaidBossCatalog.bosses {
            let expected = try XCTUnwrap(vectors.bounds[boss.slug], boss.slug)
            let b = RaidBossMath.bossBounds(boss, yaw: -0.32)
            XCTAssertEqual(b.center.x, expected.center[0], accuracy: 1e-9, boss.slug)
            XCTAssertEqual(b.center.y, expected.center[1], accuracy: 1e-9, boss.slug)
            XCTAssertEqual(b.center.z, expected.center[2], accuracy: 1e-9, boss.slug)
            XCTAssertEqual(b.radius, expected.radius, accuracy: 1e-9, boss.slug)
            XCTAssertEqual(b.halfWidth, expected.halfWidth, accuracy: 1e-9, boss.slug)
            XCTAssertEqual(b.halfHeight, expected.halfHeight, accuracy: 1e-9, boss.slug)
        }
    }

    func testRaidPhaseForMatchesTypeScript() throws {
        let vectors = try loadVectors()
        for c in vectors.phases {
            XCTAssertEqual(
                RaidBossMath.raidPhaseFor(damage: c.damage, maxHp: c.maxHp), c.phase,
                "damage \(c.damage)/\(c.maxHp)"
            )
        }
        XCTAssertEqual(RaidBossMath.raidPhaseFor(damage: 0, maxHp: 0), 0)
    }
}
